{
  "schema_version": "0.2",
  "message": "Workflow to read both printed text and barcodes from the whole image using apple-vision for both readers.",
  "questions": [],
  "graphs": [
    {
      "name": "ReadTextAndBarcodes",
      "nodes": [
        {
          "type": "frame_sample",
          "id": "s",
          "fps": 2.0
        },
        {
          "type": "ocr",
          "id": "ocr_reader",
          "image": "$s.frame",
          "model_capability_id": "model.apple-vision",
          "model_reason": "Eligible OCR"
        },
        {
          "type": "barcode",
          "id": "barcode_reader",
          "image": "$s.frame",
          "model_capability_id": "model.apple-vision",
          "model_reason": "Eligible barcode reader"
        },
        {
          "type": "match",
          "id": "ocr_match",
          "text": "$ocr_reader.text",
          "expected": "not_applicable",
          "mode": "exact",
          "emit": "all"
        },
        {
          "type": "match",
          "id": "barcode_match",
          "text": "$barcode_reader.text",
          "expected": "not_applicable",
          "mode": "exact",
          "emit": "all"
        }
      ],
      "metric": "text_accuracy",
      "target": 0.9
    }
  ]
}

